<?php get_header(); ?><main id="content" class="site-content rp-container"><?php if(is_search()):?><header class="page-heading"><h1><?php printf(esc_html__('Search results for: %s','rss-prism'),esc_html(get_search_query()));?></h1><?php get_search_form();?></header><?php elseif(is_archive()):?><header class="page-heading"><h1><?php the_archive_title();?></h1><?php the_archive_description();?></header><?php endif;?><div class="single-layout<?php echo get_theme_mod('rss_prism_show_sidebar',true)&&is_active_sidebar('sidebar-1')?'':' single-layout--no-sidebar';?>"><div><?php if(have_posts()):?><div class="entry-grid"><?php while(have_posts()):the_post();if(is_singular()):?><article <?php post_class('entry-card'); ?>><h1 class="entry-title"><?php the_title();?></h1><?php rss_prism_meta();if(has_post_thumbnail())the_post_thumbnail('large');?><div class="entry-content"><?php the_content();wp_link_pages();?></div><?php if(comments_open()||get_comments_number())comments_template();?></article><?php else:rss_prism_post_card();endif;endwhile;?></div><?php the_posts_pagination();else:?><section class="entry-card"><h1><?php echo esc_html(is_search()?__('No results found','rss-prism'):__('Nothing here yet','rss-prism'));?></h1><?php get_search_form();?></section><?php endif;?></div><?php rss_prism_sidebar();?></div></main><?php get_footer();?>